<script setup>import{reactive,ref}from'vue';import{useRouter}from'vue-router';import{ElMessage}from'element-plus';import{useAuthStore}from'../stores/auth.js';const router=useRouter(),auth=useAuthStore(),loading=ref(false),form=reactive({username:'',nickname:'',email:'',password:''});const submit=async()=>{loading.value=true;try{await auth.register(form);ElMessage.success('注册成功，欢迎加入山海迹');router.push('/')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}</script>
<template><div class="auth-page"><div class="auth-visual" :style="{backgroundImage:`linear-gradient(rgba(8,42,49,.08),rgba(8,42,49,.68)),url(/uploads/demo/banners/banner-007.png)`}"><router-link to="/" class="auth-logo"><img src="/uploads/demo/logo.png">山海迹</router-link><div><span>START YOUR STORY</span><h1>把走过的路，<br>写给准备出发的人</h1><p>注册后收藏旅行灵感、创建个人路线，也可以成为创作者分享真实攻略。</p></div></div><div class="auth-panel"><div class="auth-box"><span class="eyebrow">CREATE ACCOUNT</span><h2>加入山海迹</h2><p>只收集完成社区功能所需的信息</p><el-form label-position="top"><el-form-item label="用户名"><el-input v-model="form.username" size="large" placeholder="4–24 位用户名"/></el-form-item><el-form-item label="昵称"><el-input v-model="form.nickname" size="large" placeholder="旅行者昵称"/></el-form-item><el-form-item label="邮箱（选填）"><el-input v-model="form.email" size="large" placeholder="用于账号联系"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" show-password size="large" placeholder="至少 6 位"/></el-form-item><el-button type="primary" size="large" :loading="loading" class="full" @click="submit">创建账号</el-button></el-form><p class="switch">已有账号？<router-link to="/login">返回登录</router-link></p></div></div></div></template>
<style scoped src="../assets/auth.css"></style>

